interface AreaJamMarkProps {
  className?: string;
  color?: string;
  decorative?: boolean;
}

/** Standalone AreaJam clef-inspired monogram mark (minimum recommended width: 32px). */
export function AreaJamMark({
  className,
  color = 'var(--brand-pink, #D91B4C)',
  decorative = true,
}: AreaJamMarkProps) {
  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      viewBox="0 0 1100 1039"
      preserveAspectRatio="xMidYMid meet"
      className={className}
      aria-hidden={decorative ? true : undefined}
      role={decorative ? undefined : 'img'}
    >
      {!decorative && <title>AreaJam</title>}
      <path
        fill={color}
        fillRule="evenodd"
        transform="translate(50 50)"
        d={AREAJAM_MARK_PATH}
      />
    </svg>
  );
}

interface AreaJamLogoProps {
  className?: string;
  markColor?: string;
  wordmarkColor?: string;
  decorative?: boolean;
}

/** Official horizontal AreaJam brand lockup (recommended minimum width: 160px). */
export function AreaJamLogo({
  className,
  markColor = 'var(--brand-pink, #D91B4C)',
  wordmarkColor = 'currentColor',
  decorative = false,
}: AreaJamLogoProps) {
  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      viewBox="0 0 1600 390"
      preserveAspectRatio="xMidYMid meet"
      className={className}
      aria-hidden={decorative ? true : undefined}
      role={decorative ? undefined : 'img'}
    >
      {!decorative && <title>AreaJam</title>}
      <path
        fill={markColor}
        fillRule="evenodd"
        transform="translate(65 45) scale(0.3108)"
        d={AREAJAM_MARK_PATH}
      />
      <g
        fill={wordmarkColor}
        transform="translate(442.400 269.614) scale(0.1998000 -0.1998000)"
      >
        <OutlinedWordmarkPaths />
      </g>
    </svg>
  );
}

/** Official stacked AreaJam brand lockup for large vertical cards and modals. */
export function AreaJamStackedLogo({
  className,
  markColor = 'var(--brand-pink, #D91B4C)',
  wordmarkColor = 'currentColor',
  decorative = false,
}: AreaJamLogoProps) {
  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      viewBox="0 0 1100 800"
      preserveAspectRatio="xMidYMid meet"
      className={className}
      aria-hidden={decorative ? true : undefined}
      role={decorative ? undefined : 'img'}
    >
      {!decorative && <title>AreaJam</title>}
      <path
        fill={markColor}
        fillRule="evenodd"
        transform="translate(300 35) scale(0.5)"
        d={AREAJAM_MARK_PATH}
      />
      <g
        fill={wordmarkColor}
        transform="translate(100.600 714.283) scale(0.2100000 -0.2100000)"
      >
        <OutlinedWordmarkPaths />
      </g>
    </svg>
  );
}

/** Architectural acoustic contour arcs matching the AreaJam Pink Signature identity. */
export function BrandContourBackdrop({ mode }: { mode: AppMode }) {
  const stroke = mode === 'jam' ? 'var(--brand-contour)' : 'var(--brand-contour-gigs)';
  return (
    <div className="pointer-events-none fixed inset-0 overflow-hidden" aria-hidden="true">
      <svg
        viewBox="0 0 1440 900"
        preserveAspectRatio="xMidYMid slice"
        className="h-full w-full transition-colors duration-500"
      >
        <g fill="none" stroke={stroke} strokeWidth="2">
          {[140, 240, 340, 440, 540, 640, 740].map((r) => (
            <circle key={`br-${r}`} cx="1354" cy="756" r={r} />
          ))}
        </g>
        <g fill="none" stroke={stroke} strokeWidth="1.5" opacity="0.65">
          {[120, 210, 300].map((r) => (
            <circle key={`tl-${r}`} cx="80" cy="110" r={r} />
          ))}
        </g>
      </svg>
    </div>
  );
}
